package com.bank.topology;

import java.util.logging.Logger;

public class RedundantLinkFinder {

    private static final Logger log = Logger.getLogger(RedundantLinkFinder.class.getName());
    private int[] parent;

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    // returns the redundant edge {u, v}
    public int[] findRedundant(int[][] edges) {
        int n = edges.length;                 // tree + 1 edge ⇒ nodes = n
        parent = new int[n + 1];
        for (int i = 1; i <= n; i++) parent[i] = i;
        for (int[] e : edges) {
            int ru = find(e[0]), rv = find(e[1]);
            if (ru == rv) {
                log.severe(() -> "Redundant link detected: " + e[0] + "-" + e[1]);
                return e;                     // closes a cycle
            }
            parent[ru] = rv;                  // union
            log.info(() -> "Linked branches " + e[0] + "-" + e[1]);
        }
        return new int[0];                    // no redundant edge (shouldn't happen)
    }
}
