package com.bank.topology;

import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class RedundantLinkDemo {

    private static final Logger log = Logger.getLogger(RedundantLinkDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Topology Repair (Redundant Link)");
        int[][] links = {{1, 2}, {1, 3}, {2, 3}}; // 2-3 closes the cycle
        RedundantLinkFinder finder = new RedundantLinkFinder();
        int[] bad = finder.findRedundant(links);
        log.info("Remove link: " + Arrays.toString(bad));
    }
}
